// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guess, uint256 fakeBlockHash) public {
        // Make sure the fuzzed block hash is nonzero so that keccak256(abi.encodePacked(uint256(0))) is
        // the only "unmatched" answer the mutant can pay against outside the guess block.
        vm.assume(fakeBlockHash != 0);

        address actor = address(0xBEEF);
        vm.deal(actor, 2 ether);

        // Actor commits a guess that is NOT the answer for any past block except possibly the
        // zero-hash answer, which is the mutant's answer outside the guess block.
        bytes32 committed = keccak256(abi.encodePacked(uint256(0)));
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(committed);

        uint256 guessBlock = block.number + 1;

        // Advance past the stored guess block so settle can run.
        vm.roll(guessBlock + 1);

        // Record whether the actor receives the prize.
        uint256 beforeBal = actor.balance;

        vm.prank(actor);
        c.settle();

        uint256 afterBal = actor.balance;

        // General rule: a payout is allowed only if the committed guess equals the true answer.
        // Since committed = keccak256(abi.encodePacked(uint256(0))), the only way a payout is correct
        // is if the true blockhash of the stored guess block was zero. Outside the guess block the
        // mutant computes blockhash(block.number) = 0 and pays, violating the rule.
        bool trueAnswerMatches = (committed == keccak256(abi.encodePacked(blockhash(guessBlock))));
        bool paid = (afterBal == beforeBal + 2 ether);

        assertTrue(!paid || trueAnswerMatches);
    }
}
